177	pub fn print_diff(actual: &str, expected: &str) {
178	    let changeset = Changeset::new(actual, expected, "\n");
179	    for diff in &changeset.diffs {
180	        match diff {
181	            Difference::Same(part) => {
182	                print!("{part}{}", changeset.split);
183	            }
184	            Difference::Add(part) => {
185	                print!("{}{}", Colour::Green.paint(part), changeset.split);
186	            }
187	            Difference::Rem(part) => {
188	                print!("{}{}", Colour::Red.paint(part), changeset.split);
189	            }
190	        }
191	    }
192	    println!();
193	}
